package com.hbm.machine.anvil;
import com.google.gson.*;
import com.hbm.hazard.HbmHazards;
import com.hbm.item.autogen.AutogenContent;
import com.hbm.material.*;
import com.hbm.recipe.LegacyOreIngredient;
import com.hbm.registry.HbmOreDictionary;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Original construction replacement file, source mode flags and all three runtime material loops. */
public final class AnvilRecipeConfig{
    private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final List<String> UNBOUND=new ArrayList<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();
    private AnvilRecipeConfig(){}public static List<String> unresolved(){return List.copyOf(UNBOUND);}
    static void register(){try(var stream=AnvilRecipeConfig.class.getResourceAsStream("/hbm/anvil-item-aliases.json")){if(stream!=null)JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(entry->ALIASES.put(entry.getKey(),entry.getValue().getAsString()));}catch(java.io.IOException error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener(AnvilRecipeConfig::starting);NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,AnvilRecipeConfig::sync);}
    private static void starting(ServerAboutToStartEvent event){install(event.getServer());}private static void sync(OnDatapackSyncEvent event){if(event.getPlayer()==null||!INSTALLED.containsKey(event.getPlayerList().getServer().getRecipeManager()))install(event.getPlayerList().getServer());}
    public static void reload(MinecraftServer server) { install(server); }
    private static void install(MinecraftServer server){RecipeManager manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var generated=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();UNBOUND.clear();boolean expensive=com.hbm.config.GeneralModes.expensive(),unlock=com.hbm.config.GeneralModes.lbsm("LBSM_recipeUnlockAnvil"),mode528=com.hbm.config.GeneralModes.mode528();Path directory=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=directory.resolve("hbmAnvil.json");
        try{
            Files.createDirectories(directory);
            if(Files.isRegularFile(active)){merged.values().removeIf(holder->holder.value().getType()==AnvilContent.CONSTRUCTION_TYPE.get());JsonObject config;try(var reader=Files.newBufferedReader(active)){config=JsonParser.parseReader(reader).getAsJsonObject();}int index=0;for(var value:config.getAsJsonArray("recipes")){try{var row=value.getAsJsonObject();var inputs=new ArrayList<AnvilIngredient>();for(var data:row.getAsJsonArray("inputs"))inputs.add(legacyInput(data.getAsJsonArray()));var outputs=new ArrayList<AnvilConstructionRecipe.Output>();for(var data:row.getAsJsonArray("outputs")){var spec=data.getAsJsonArray();ItemStack stack=legacyStack(spec.get(0).getAsString(),spec.size()>3?spec.get(2).getAsInt():0);if(stack.isEmpty())throw new IllegalArgumentException("Unregistered output "+spec.get(0));stack.setCount(spec.size()>2?spec.get(1).getAsInt():1);if(spec.size()>4)stack.set(DataComponents.CUSTOM_DATA,CustomData.of(TagParser.parseTag(spec.get(3).getAsString())));outputs.add(new AnvilConstructionRecipe.Output(stack,spec.get(spec.size()-1).getAsFloat()));}int lower=unlock?1:row.get("tierLower").getAsInt(),upper=unlock?1:row.has("tierUpper")?row.get("tierUpper").getAsInt():-1;put(generated,"construction/config/"+index,new AnvilConstructionRecipe(inputs,outputs,lower,upper,row.has("overlay")?row.get("overlay").getAsString():"NONE",index));}catch(Exception error){UNBOUND.add("config row "+index+": "+error.getMessage());}index++;}}
            else{try(var template=AnvilRecipeConfig.class.getResourceAsStream("/hbm/anvil-recipe-template.json")){if(template!=null)Files.copy(template,directory.resolve("_hbmAnvil.json"),StandardCopyOption.REPLACE_EXISTING);}generateMaterials(merged,generated,unlock);}
            // Resolve server flags into ordinary native recipe holders before login/reload sync.
            for(var holder:List.copyOf(merged.values()))if(holder.value() instanceof AnvilConstructionRecipe recipe){if(mode528&&recipe.sourceMode().equals("not528")){merged.remove(holder.id());continue;}if(unlock||expensive&&!recipe.expensiveInputs().isEmpty()) {var adjusted=new AnvilConstructionRecipe(expensive&&!recipe.expensiveInputs().isEmpty()?recipe.expensiveInputs():recipe.inputs(),recipe.outputs(),unlock?1:recipe.lower(),recipe.upper(),recipe.overlay(),recipe.order());generated.put(holder.id(),new RecipeHolder<>(holder.id(),adjusted));}}
            else if(unlock&&holder.value() instanceof AnvilSmithingRecipe recipe){var adjusted=new AnvilSmithingRecipe(recipe.left(),recipe.right(),recipe.output(),1,recipe.kind(),recipe.shapeless(),recipe.prefix(),recipe.exactLeft(),recipe.order());generated.put(holder.id(),new RecipeHolder<>(holder.id(),adjusted));}
        }catch(Exception error){LogUtils.getLogger().error("Cannot load original anvil configuration",error);}generated.forEach(merged::put);if(!Files.isRegularFile(active))try{writeTemplate(directory.resolve("_hbmAnvil.json"),merged.values());}catch(Exception error){LogUtils.getLogger().error("Cannot write complete native anvil recipe template",error);}manager.replaceRecipes(merged.values());INSTALLED.put(manager,generated);UNBOUND.forEach(error->LogUtils.getLogger().warn("Unbound anvil recipe: {}",error));}

    private static void writeTemplate(Path path,Collection<RecipeHolder<?>> holders)throws java.io.IOException{JsonObject root=new JsonObject();JsonArray rows=new JsonArray();for(var holder:holders)if(holder.value() instanceof AnvilConstructionRecipe recipe){try{JsonObject row=new JsonObject();JsonArray inputs=new JsonArray(),outputs=new JsonArray();for(var input:recipe.inputs()){var custom=input.ingredient().getCustomIngredient();JsonArray spec=new JsonArray();if(custom instanceof com.hbm.recipe.SourceFluidContainerIngredient fluid){spec.add("dict");spec.add(com.hbm.fluid.HbmFluids.fromName(fluid.fluid()).getDict(fluid.amount(),com.hbm.fluid.FluidContainerConfig.CONTAINER_COMPAT.get()));spec.add(input.count());}else if(custom instanceof LegacyOreIngredient ore){String raw=HbmOreDictionary.allNames().stream().filter(name->("hbm:legacy_ore_dict/"+name.toLowerCase(Locale.ROOT)).equals(ore.tag().toString())).findFirst().orElse(ore.tag().getPath().substring("legacy_ore_dict/".length()));spec.add("dict");spec.add(raw);spec.add(input.count());}else{ItemStack stack;CompoundTag nbt=null;if(custom instanceof com.hbm.machine.alloy.AlloyStackIngredient exact)stack=exact.stack();else if(custom instanceof com.hbm.machine.centrifuge.CentrifugeNbtIngredient exact){stack=exact.example();nbt=exact.required();}else{var examples=input.ingredient().getItems();if(examples.length!=1)throw new IllegalArgumentException("Native ingredient cannot be represented by one original AStack");stack=examples[0];}spec.add(nbt==null?"item":"nbt");spec.add(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString());spec.add(input.count());spec.add(stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue()));if(nbt!=null)spec.add(nbt.toString());}inputs.add(spec);}for(var output:recipe.outputs()){ItemStack stack=output.stack();JsonArray spec=new JsonArray();spec.add(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString());spec.add(stack.getCount());spec.add(stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue()));if(stack.has(DataComponents.CUSTOM_DATA))spec.add(stack.get(DataComponents.CUSTOM_DATA).copyTag().toString());spec.add(output.chance());outputs.add(spec);}row.add("inputs",inputs);row.add("outputs",outputs);row.addProperty("tierLower",recipe.lower());row.addProperty("tierUpper",recipe.upper());row.addProperty("overlay",recipe.overlay());rows.add(row);}catch(Exception error){UNBOUND.add("template "+holder.id()+": "+error.getMessage());}}root.add("recipes",rows);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}
    private static boolean flag(JsonObject object,String key,boolean fallback){return object.has(key)?object.get(key).getAsBoolean():fallback;}
    private static void put(Map<ResourceLocation,RecipeHolder<?>> values,String path,AnvilConstructionRecipe recipe){ResourceLocation id=ResourceLocation.fromNamespaceAndPath("hbm","anvil/"+path);values.put(id,new RecipeHolder<>(id,recipe));}
    private static AnvilIngredient ore(String name,int count){return new AnvilIngredient(new LegacyOreIngredient(ResourceLocation.parse(HbmOreDictionary.registerName(name))).toVanilla(),count);}
    private static void generateMaterials(Map<ResourceLocation,RecipeHolder<?>> existing,Map<ResourceLocation,RecipeHolder<?>> generated,boolean unlock){Set<String> names=Set.copyOf(HbmOreDictionary.allNames());int index=0;for(NtmMaterial mat:HbmMaterials.ordered()){
        MaterialShape wire=HbmMaterials.shape("WIRE"),shell=HbmMaterials.shape("SHELL"),pipe=HbmMaterials.shape("PIPE"),ingot=HbmMaterials.shape("INGOT"),plate=HbmMaterials.shape("PLATE");
        if(mat.autogen().contains(wire)&&names.contains(ingot.make(mat)))material(existing,generated,mat,"wire",ore(ingot.make(mat),1),mat.make(AutogenContent.item("wire_fine"),8),unlock?1:4,157000000+index);
        if(mat.autogen().contains(shell))material(existing,generated,mat,"shell",ore(plate.make(mat),4),mat.make(AutogenContent.item("shell")),1,194000000+index);
        if(mat.autogen().contains(pipe))material(existing,generated,mat,"pipe",ore(names.contains(plate.make(mat))?plate.make(mat):ingot.make(mat),3),mat.make(AutogenContent.item("pipe")),1,201000000+index);index++;}}
    private static void material(Map<ResourceLocation,RecipeHolder<?>> existing,Map<ResourceLocation,RecipeHolder<?>> generated,NtmMaterial mat,String shape,AnvilIngredient input,ItemStack output,int tier,int order){String path="construction/material_"+shape+"/"+mat.id();ResourceLocation id=ResourceLocation.fromNamespaceAndPath("hbm","anvil/"+path);if(existing.containsKey(id))return;put(generated,path,new AnvilConstructionRecipe(List.of(input),List.of(new AnvilConstructionRecipe.Output(output,1)),tier,-1,"SMITHING",order));}
    private static AnvilIngredient legacyInput(JsonArray spec)throws Exception{String kind=spec.get(0).getAsString(),name=spec.get(1).getAsString();int count=spec.size()>2?spec.get(2).getAsInt():1;if(kind.equals("dict"))return ore(name,count);ItemStack stack=legacyStack(name,kind.equals("nbt")?0:spec.size()>3?spec.get(3).getAsInt():0);if(stack.isEmpty())throw new IllegalArgumentException("Unregistered input "+name);if(kind.equals("nbt"))return new AnvilIngredient(new com.hbm.machine.centrifuge.CentrifugeNbtIngredient(stack,spec.size()>4?TagParser.parseTag(spec.get(4).getAsString()):new CompoundTag()).toVanilla(),count);if(!kind.equals("item"))throw new IllegalArgumentException("Unknown original AStack "+kind);return new AnvilIngredient(new com.hbm.machine.alloy.AlloyStackIngredient(stack).toVanilla(),count);}
    private static ItemStack legacyStack(String old,int metadata){ItemStack stack=MaterialDistributionConfig.legacyStack(ALIASES.getOrDefault(old,old),metadata);if(!stack.isEmpty()&&com.hbm.item.fluid.FluidItemContent.subtypedItems().contains(stack.getItem()))com.hbm.item.fluid.FluidItemContent.setType(stack,com.hbm.fluid.HbmFluids.fromID(metadata));if(!stack.isEmpty()&&metadata==0&&!stack.getItem().components().has(HbmHazards.LEGACY_METADATA.get()))stack.remove(HbmHazards.LEGACY_METADATA.get());return stack;}
}
